-- Prediction Query
SELECT CAST((STRFTIME('%Y', '2025-01-01 00:00:00') - STRFTIME('%Y', T1.birthday)) AS INTEGER) - (STRFTIME('%m', '2025-01-01 00:00:00') < STRFTIME('%m', T1.birthday) OR (STRFTIME('%m', '2025-01-01 00:00:00') = STRFTIME('%m', T1.birthday) AND STRFTIME('%d', '2025-01-01 00:00:00') < STRFTIME('%d', T1.birthday))) AS age FROM Player AS T1 INNER JOIN Player_Attributes AS T2 ON T1.player_api_id = T2.player_api_id WHERE T2.sprint_speed >= 97 AND STRFTIME('%Y', T2.date) BETWEEN '2013' AND '2015';

